import java.nio.file.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class OtherRequiredApi {
 static MethodNode find(ClassNode c,String k){return c.methods.stream().filter(m->OpeningDelta.key(m).equals(k)).findFirst().orElseThrow();}
 public static void main(String[]a)throws Exception{var current=OpeningDelta.read(Files.readAllBytes(Path.of(a[0])),0);var fresh=OpeningDelta.read(Files.readAllBytes(Path.of(a[1])),0);var old=OpeningDelta.read(Files.readAllBytes(Path.of(a[2])),0);String key=a[3];if(current.methods.stream().anyMatch(m->OpeningDelta.key(m).equals(key)))throw new IllegalStateException("API already exists");var m=find(fresh,key);if(!OpeningDelta.norm(m).equals(OpeningDelta.norm(find(old,key))))throw new IllegalStateException("source baseline API differs");var added=new MethodNode(m.access,m.name,m.desc,m.signature,m.exceptions.toArray(String[]::new));m.accept(added);current.methods.add(added);var w=new ClassWriter(ClassWriter.COMPUTE_MAXS);current.accept(w);byte[] bytes=w.toByteArray();var verified=OpeningDelta.read(bytes,0);for(var x:verified.methods)if((x.access&1280)==0)new Analyzer<BasicValue>(new BasicVerifier()).analyze(verified.name,x);Files.write(Path.of(a[4]),bytes);System.out.println("PASS REQUIRED_API "+verified.name+" "+key+" liveAbsent=true exactBaselineSourceBody=true existingMethodsUnmodified=true");}
}